#let diagram = cetz.canvas({
  import cetz.draw: *

  // Diamond with center node M
  //   A
  //  /|\
  // P | Q
  //  \|/
  //   M
  //  /|\
  // P | Q  (different positions in 2D -- shown as a single rhombus below)
  //  \|/
  //   B
  //
  // Actually: a diamond (A top, P left, B bottom, Q right)
  // with both diagonals drawn (P-Q horizontal, A-M + M-B vertical)

  let A = (0, 3)
  let P = (-3, 0)
  let B = (0, -3)
  let Q = (3, 0)
  let M = (0, 0)

  // Diamond sides
  line(A, P, stroke: black + 1.6pt)
  line(A, Q, stroke: black + 1.6pt)
  line(P, B, stroke: black + 1.6pt)
  line(Q, B, stroke: black + 1.6pt)

  // Horizontal diagonal P-Q
  line(P, Q, stroke: black + 1.6pt)

  // Vertical diameter A-M-B (split at center)
  line(A, M, stroke: black + 1.6pt)
  line(M, B, stroke: black + 1.6pt)

  // Resistor label on each edge
  for (p, q) in (((A, P), (A, Q), (P, B), (Q, B), (P, Q), (A, M), (M, B))) {
