#let diagram = cetz.canvas({
  import cetz.draw: *

  // Wall (vertical line on left)
  line((0, 0), (0, 5), stroke: 2pt + black)

  // Hatching on wall
  for i in range(11) {
    let y = i * 0.5
    line((-0.15, y + 0.05), (-0.35, y + 0.05), stroke: 1pt + gray)
  }

  // Point O (hinge) on wall
  circle((0, 2.5), radius: 0.08, fill: black)
  content((-0.45, 2.5), anchor: "east", text(size: 15pt)[$O$])

  // Rod OX (horizontal from O to X)
  let x-end = 4
  line((0, 2.5), (x-end, 2.5), stroke: 2.4pt + rgb("#8b4513"))
  circle((x-end, 2.5), radius: 0.08, fill: black)
  content((x-end + 0.15, 2.5), anchor: "west", text(size: 15pt)[$X$])

  // Midpoint M
  let mid-x = x-end / 2
  circle((mid-x, 2.5), radius: 0.1, fill: rgb("#ffaa00"))
  content((mid-x, 2.85), text(size: 14pt)[$M$])

  // Point Y on wall above O
  let y-point = 4.5
  circle((0, y-point), radius: 0.08, fill: black)
  content((-0.45, y-point), anchor: "east", text(size: 15pt)[$Y$])

  // String MY (dashed)
  line((mid-x, 2.5), (0, y-point), stroke: (dash: "dashed", thickness: 1.6pt + rgb("#1a7f37")))
  // Tension label
  content((mid-x * 0.55, 3.65), text(size: 13pt, fill: rgb("#1a7f37"))[string])

  // Weight W hanging from X
  line((x-end, 2.5), (x-end, 1.0), stroke: 1.4pt)
  // Weight block
  rect((x-end - 0.25, 0.5), (x-end + 0.25, 1.0), fill: rgb("#555"), stroke: 1.6pt)
  content((x-end, 0.2), text(size: 14pt)[$W$])

  // Angle markings - four directions OP, OQ, OR, OS emanating from O
  // We'll draw them as arrows going into the page slightly, in the gap area
  // Actually, OP/OQ/OR/OS are typically inside or near the rod area showing force direction choices

  // Draw four candidate reaction directions as dashed arrows from O
  // OP: along MY (up-left)
  // OQ: along MX (right) - along rod
  // OR: downward-left (perpendicular into wall)
  // OS: down-right at some angle

  // OP: along the string direction (up-left toward Y)
  line((0, 2.5), (-1.6, y-point - 2.5 + 2.5), mark: (end: "stealth", scale: 1.3),
    stroke: (dash: "dashed", thickness: 1.4pt + rgb("#e74c3c")))
  content((-1.85, 3.8), text(size: 14pt, fill: rgb("#e74c3c"))[$P$])

  // OQ: along the rod (right)
  line((0, 2.5), (1.4, 2.5), mark: (end: "stealth", scale: 1.3),
    stroke: (dash: "dashed", thickness: 1.4pt + rgb("#e74c3c")))
  content((1.6, 2.5), anchor: "west", text(size: 14pt, fill: rgb("#e74c3c"))[$Q$])

  // OR: downward at 45 deg (right-down)
  line((0, 2.5), (1.0, 1.5), mark: (end: "stealth", scale: 1.3),
    stroke: (dash: "dashed", thickness: 1.4pt + rgb("#e74c3c")))
  content((0.85, 1.3), text(size: 14pt, fill: rgb("#e74c3c"))[$R$])

  // OS: straight down
  line((0, 2.5), (0, 1.1), mark: (end: "stealth", scale: 1.3),
    stroke: (dash: "dashed", thickness: 1.4pt + rgb("#e74c3c")))
  content((0.3, 1.7), text(size: 14pt, fill: rgb("#e74c3c"))[$S$])

  // Small angle arc at M
  arc((mid-x, 2.5), start: 0deg, stop: -45deg, radius: 0.3,
    stroke: 1pt + gray, mode: "OPEN")
})

