    line((0, 2.5), (ex, 2.5 + ey), mark: (end: ">"),
      stroke: (paint: rgb("#e74c3c"), thickness: 1.5pt, dash: "dashed"))
    content((lx, ly), text(size: 15pt, fill: rgb("#e74c3c"))[#lbl])
  }

